use vstd::prelude::*;

verus! {

fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> (replaced_list: Vec<i32>)
    requires
        first.len() > 0,
        // capacity computation must not underflow/overflow `usize`
        first.len() - 1 + second.len() <= usize::MAX,
    ensures
        replaced_list.len() == first.len() - 1 + second.len(),
        // prefix comes from `first` without its last element
        forall|i: int|
            0 <= i < (first.len() - 1) as int ==>
                replaced_list[i] == first[i],
        // suffix comes from `second`
        forall|j: int|
            0 <= j < second.len() as int ==>
                replaced_list[(first.len() - 1) as int + j] == second[j],
{
    assert!(!first.is_empty(), "first array must be non-empty");

    let mut replaced_list = Vec::with_capacity(first.len() - 1 + second.len());
    replaced_list.extend_from_slice(&first[..first.len() - 1]);
    replaced_list.extend_from_slice(second);

    replaced_list
}

}

